INSERT INTO `field_revision_body` VALUES ('node','testimonial',0,38,38,'und',0,'The most important thing TSM gave me is confidence. IT qualifications encouraged me to go for better jobs. The TSM instructors were excellent. I am currently a CCNA and working towards MCSA. I feel really Confident that I have the real hands on knowledge which is expected in industry.','','plain_text'),('node','testimonial',0,39,39,'und',0,'I have greatly enjoyed my time at TSM. I learned a lot here, they not only helped me with my course but they also helped me with my CV and interview skills. Thanks to them I feel more confident.','','plain_text'),('node','page',0,40,40,'und',0,'<div id=\"coursesweoffer\" class=\"row-fluid\"></div>','','full_html'),('node','page',0,47,47,'und',0,'<div id=\"frontpage\" class=\"row-fluid columns-wrapper\"></div>','','php_code'),('node','article',0,48,48,'und',0,'We have got many spaces for two test centres. \r\n\r\nPROMETRIC and PEARSON VUE.','','full_html'),('node','article',0,49,49,'und',0,'IT Solutions Content','','full_html'),('node','article',0,50,50,'und',0,'IT Support Content','','full_html');
