INSERT INTO `search_dataset` VALUES (37,'node',' success stories ',0),(38,'node',' ajay the most important thing tsm gave me is confidence it qualifications encouraged me to go for better jobs the tsm instructors were excellent i am currently a ccna and working towards mcsa i feel really confident that i have the real hands on knowledge which is expected in industry  ',0),(39,'node',' moushmi i have greatly enjoyed my time at tsm i learned a lot here they not only helped me with my course but they also helped me with my cv and interview skills thanks to them i feel more confident  ',0),(40,'node',' courses we offer ',0),(43,'node',' contact us ',0),(44,'node',' courses information ',0),(45,'node',' terms and conditions ',0),(46,'node',' privacy ',0),(47,'node',' home page ',0),(48,'node',' test centres we have got many spaces for two test centres prometric and pearson vue  ',0),(49,'node',' it solutions it solutions content  ',0),(50,'node',' it support it support content  ',0),(51,'node',' sample true  ',0);
/*!40000 ALTER TABLE `search_dataset` ENABLE KEYS */;
UNLOCK TABLES;

